from datetime import datetime

class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time")

        # Calculate the duration in seconds and convert to hours
        duration = exit - entry
        total_seconds = duration.total_seconds()

        # Check if stay is longer than 24 hours (24 * 3600 = 86400 seconds)
        if total_seconds > 86400:
            return round(200.00, 2)

        # Convert duration to hours, rounding up to the next hour for any partial hour
        # Total hours = ceil(total_seconds / 3600)
        hours = (total_seconds + 3599) // 3600  # This effectively does ceiling division for positive numbers

        # Calculate fee and round to two decimal places
        fee_amount = hours * self.hourly_rate
        return round(fee_amount, 2)
